@props(['name', 'label', 'icon' => '📍', 'placeholder' => 'Selecciona una opción', 'options' => [], 'selected' => null])
@php
 $items=collect($options)->map(fn($text,$value)=>['value'=>(string)$value,'text'=>(string)$text])->values();
 $selectedText=$items->firstWhere('value',(string)$selected)['text']??$placeholder;
@endphp
<div data-public-select data-placeholder="{{$placeholder}}" class="relative min-w-0 {{ $attributes->get('class') }}">
 <input data-public-select-input type="hidden" id="{{$name}}" name="{{$name}}" value="{{$selected}}">
 <button data-public-select-trigger type="button" aria-haspopup="listbox" aria-expanded="false" class="flex h-[58px] w-full items-center gap-2.5 rounded-lg border border-slate-200 bg-white px-3 text-left shadow-sm transition hover:border-emerald-300 hover:shadow-md focus:border-emerald-600 focus:outline-none focus:ring-4 focus:ring-emerald-600/10">
  <span class="grid h-8 w-8 shrink-0 place-items-center rounded-md bg-emerald-50 text-sm">{{$icon}}</span><span class="min-w-0 flex-1"><span class="block text-[9px] font-bold uppercase tracking-wider text-slate-400">{{$label}}</span><strong data-public-select-label class="block truncate text-sm font-bold {{$selected?'text-slate-900':'text-slate-500'}}">{{$selectedText}}</strong></span><svg data-public-select-chevron class="h-4 w-4 shrink-0 text-emerald-700 transition" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>
 </button>
 <div data-public-select-menu role="listbox" class="absolute left-0 right-0 top-[64px] z-[80] hidden max-h-64 overflow-y-auto rounded-lg border border-slate-200 bg-white p-1.5 shadow-2xl shadow-slate-900/20">
  <div class="px-3 py-2 text-[9px] font-black uppercase tracking-[.14em] text-slate-400">{{$placeholder}}</div>
  @foreach($items as $item)<button data-public-select-option type="button" role="option" data-value="{{$item['value']}}" data-label="{{$item['text']}}" aria-selected="{{(string)$selected===$item['value']?'true':'false'}}" class="flex w-full items-center justify-between rounded-md px-3 py-2.5 text-left text-sm font-semibold text-slate-700 transition hover:bg-emerald-50 hover:text-emerald-900 focus:bg-emerald-50 focus:outline-none"><span>{{$item['text']}}</span><span data-public-select-check class="{{(string)$selected===$item['value']?'':'invisible'}} grid h-6 w-6 place-items-center rounded-md bg-emerald-600 text-xs text-white">✓</span></button>@endforeach
 </div>
</div>
@once
<script>document.addEventListener('DOMContentLoaded',()=>{const roots=[...document.querySelectorAll('[data-public-select]')],close=root=>{root.querySelector('[data-public-select-menu]').classList.add('hidden');root.querySelector('[data-public-select-trigger]').setAttribute('aria-expanded','false');root.querySelector('[data-public-select-chevron]').classList.remove('rotate-180')};roots.forEach(root=>{const trigger=root.querySelector('[data-public-select-trigger]'),menu=root.querySelector('[data-public-select-menu]'),input=root.querySelector('[data-public-select-input]'),label=root.querySelector('[data-public-select-label]');trigger.addEventListener('click',()=>{const opening=menu.classList.contains('hidden');roots.forEach(close);if(opening){menu.classList.remove('hidden');trigger.setAttribute('aria-expanded','true');root.querySelector('[data-public-select-chevron]').classList.add('rotate-180')}});root.querySelectorAll('[data-public-select-option]').forEach(option=>option.addEventListener('click',()=>{input.value=option.dataset.value;label.textContent=option.dataset.label;label.classList.remove('text-slate-500');label.classList.add('text-slate-900');root.querySelectorAll('[data-public-select-option]').forEach(item=>{const selected=item===option;item.setAttribute('aria-selected',String(selected));item.querySelector('[data-public-select-check]').classList.toggle('invisible',!selected)});close(root)}));root.addEventListener('public-select:set',event=>{const option=[...root.querySelectorAll('[data-public-select-option]')].find(item=>item.dataset.value===String(event.detail.value));if(option){option.click()}else{input.value='';label.textContent=root.dataset.placeholder;label.classList.add('text-slate-500');label.classList.remove('text-slate-900');root.querySelectorAll('[data-public-select-check]').forEach(check=>check.classList.add('invisible'));close(root)}});root.addEventListener('keydown',event=>{if(event.key==='Escape'){close(root);trigger.focus()}})});document.addEventListener('click',event=>roots.forEach(root=>{if(!root.contains(event.target))close(root)}))});</script>
@endonce
